def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=5 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==5 and q not in seen:
              seen.add(q); stack.append(q)
        r0=min(y for y,x in cells); r1=max(y for y,x in cells)
        c0=min(x for y,x in cells); c1=max(x for y,x in cells)
        for y in range(r0,r1+1):
          for x in range(c0+1,c1):
            if grid[y][x]==0: out[y][x]=2
        if r0>0:
          for x in range(c1): out[r0-1][x]=2
    return out

